#include "conv_transposed_2d_asymmetric_input_asymmetric_kernel_custom_tiling.h"
#include "register/op_def_registry.h"

namespace {

static inline uint32_t GetDim(const gert::Shape* s, int idx) {
    return static_cast<uint32_t>(s->GetDim(idx));
}

}

namespace optiling {
const uint32_t BLOCK_DIM = 8;

static ge::graphStatus TilingFunc(gert::TilingContext* context)
{
    // x: [N, Cin, Hin, Win]
    // w: [Cin, Cout, Kh, Kw] (PyTorch ConvTranspose2d weight layout)
    const gert::Shape* xShape = context->GetInputShape(0);
    const gert::Shape* wShape = context->GetInputShape(1);

    uint32_t n   = GetDim(xShape, 0);
    uint32_t cin = GetDim(xShape, 1);
    uint32_t hin = GetDim(xShape, 2);
    uint32_t win = GetDim(xShape, 3);

    uint32_t cin_w = GetDim(wShape, 0);
    uint32_t cout  = GetDim(wShape, 1);
    uint32_t kh    = GetDim(wShape, 2);
    uint32_t kw    = GetDim(wShape, 3);

    // Basic validation (Cin must match)
    if (cin != cin_w) {
        return ge::GRAPH_FAILED;
    }

    // Defaults in the given Model: stride=(1,1), padding=(0,0), dilation=(1,1), output_padding=(0,0)
    // So: Hout = Hin + Kh - 1, Wout = Win + Kw - 1
    uint32_t hout = hin + kh - 1;
    uint32_t wout = win + kw - 1;

    // Simple tiling: tile along width rows
    uint32_t tileW = 256; // can be tuned

    ConvTransposed2dAsymmetricInputAsymmetricKernelCustomTilingData tiling;
    tiling.set_n(n);
    tiling.set_cin(cin);
    tiling.set_cout(cout);
    tiling.set_hin(hin);
    tiling.set_win(win);
    tiling.set_kh(kh);
    tiling.set_kw(kw);
    tiling.set_hout(hout);
    tiling.set_wout(wout);
    tiling.set_tileW(tileW);

    context->SetBlockDim(BLOCK_DIM);
    tiling.SaveToBuffer(context->GetRawTilingData()->GetData(), context->GetRawTilingData()->GetCapacity());
    context->GetRawTilingData()->SetDataSize(tiling.GetDataSize());

    size_t *currentWorkspace = context->GetWorkspaceSizes(1);
    currentWorkspace[0] = 0;
    return ge::GRAPH_SUCCESS;
}

} // namespace optiling


namespace ge {
static ge::graphStatus InferShape(gert::InferShapeContext* context)
{
    // x: [N, Cin, Hin, Win]
    // w: [Cin, Cout, Kh, Kw]
    const gert::Shape* xShape = context->GetInputShape(0);
    const gert::Shape* wShape = context->GetInputShape(1);

    uint32_t n   = static_cast<uint32_t>(xShape->GetDim(0));
    uint32_t cin = static_cast<uint32_t>(xShape->GetDim(1));
    uint32_t hin = static_cast<uint32_t>(xShape->GetDim(2));
    uint32_t win = static_cast<uint32_t>(xShape->GetDim(3));

    uint32_t cin_w = static_cast<uint32_t>(wShape->GetDim(0));
    uint32_t cout  = static_cast<uint32_t>(wShape->GetDim(1));
    uint32_t kh    = static_cast<uint32_t>(wShape->GetDim(2));
    uint32_t kw    = static_cast<uint32_t>(wShape->GetDim(3));

    if (cin != cin_w) {
        return ge::GRAPH_FAILED;
    }

    // With defaults (stride=1, padding=0, dilation=1, output_padding=0):
    uint32_t hout = hin + kh - 1;
    uint32_t wout = win + kw - 1;

    gert::Shape* yShape = context->GetOutputShape(0);
    yShape->SetDimNum(4);
    yShape->SetDim(0, static_cast<int64_t>(n));
    yShape->SetDim(1, static_cast<int64_t>(cout));
    yShape->SetDim(2, static_cast<int64_t>(hout));
    yShape->SetDim(3, static_cast<int64_t>(wout));

    return GRAPH_SUCCESS;
}

static ge::graphStatus InferDataType(gert::InferDataTypeContext *context)
{
