import torch
import torch_npu
import custom_ops_lib

class ModelNew(torch.nn.Module):
    """
    使用自定义 AscendC Kernel 替换 ConvTranspose2d 前向计算（权重参数仍由原生模块管理）。
    假定 stride=(1,1), padding=(0,0), output_padding=(0,0), dilation=(1,1), groups=1, bias=False。
    """
    def __init__(self, in_channels: int, out_channels: int, kernel_size: tuple, stride: tuple = (1, 1), padding: tuple = (0, 0), output_padding: tuple = (0, 0), dilation: tuple = (1, 1), groups: int = 1, bias: bool = False):
        super().__init__()
        assert stride == (1, 1), "当前自定义算子示例仅支持 stride=(1,1)"
        assert padding == (0, 0), "当前自定义算子示例仅支持 padding=(0,0)"
        assert output_padding == (0, 0), "当前自定义算子示例仅支持 output_padding=(0,0)"
        assert dilation == (1, 1), "当前自定义算子示例仅支持 dilation=(1,1)"
        assert groups == 1, "当前自定义算子示例仅支持 groups=1"
        assert bias is False, "当前自定义算子示例不支持 bias"

        self.conv_transpose2d = torch.nn.ConvTranspose2d(
            in_channels, out_channels, kernel_size,
            stride=stride, padding=padding, output_padding=output_padding,
            dilation=dilation, groups=groups, bias=bias
        )

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        # 直接调用自定义算子，传入输入与权重
        return custom_ops_lib.conv_transposed_2d_asymmetric_input_asymmetric_kernel_custom(x, self.conv_transpose2d.weight)
